export const getPlayerByCode = (code: string): Player | undefined => {
  const normalized = code.replace(/\s+/g, '').toUpperCase();
  return players.find(p => p.code.toUpperCase() === code.toUpperCase() || p.stickerNumber.toUpperCase() === normalized);
};

export const getPlayersByTeam = (teamCode: string): Player[] => {
  return players
    .filter(p => p.teamCode === teamCode)
    .sort((a, b) => a.albumOrder - b.albumOrder);
};
